function icon(name){ return ICONS[name] || ICONS.grid; }
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function fmtDate(v){if(!v||v==='—')return '—';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);return d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});}
function statusClass(s){const x=String(s||'').toLowerCase();if(x.includes('verified')||x.includes('active')||x.includes('approved')||x.includes('completed')||x==='pass')return 'verified';if(x.includes('expir')||x.includes('warning')||x.includes('scheduled')||x.includes('review')||x.includes('progress')||x.includes('medium'))return 'warning';if(x.includes('overdue')||x.includes('reject')||x.includes('fail')||x.includes('revoked')||x.includes('high')||x.includes('mismatch'))return 'danger';return 'pending';}

const state={route:location.hash.replace('#','')||'home',sidebarOpen:false,drawerOpen:false,currentUser:null,csrf:'',selectedInstrument:'LM-2026-00123',selectedApplication:'',selectedInspection:'',selectedComplaint:'',selectedFeedbackInspection:'',selectedGatc:'',instrumentTab:'Overview',authMode:'login',authRole:'business',currentInspectionRule:null,currentInspection:null};
