let warmLandingCleanup=null;
function initWarmLanding(){
  if(warmLandingCleanup)warmLandingCleanup();
  const root=document.querySelector('.warm-landing');
  if(!root)return;
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const revealTargets=[...root.querySelectorAll('.warm-trace-bucket,.warm-story-card,.warm-role-card,.warm-life-row,.warm-trust-shell,.warm-final-cta,.warm-trust-ribbon,.warm-process')];
  if(!reduced && 'IntersectionObserver' in window){
    const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}}),{threshold:.14,rootMargin:'0px 0px -30px'});
    revealTargets.forEach((el,i)=>{el.style.setProperty('--reveal-delay',`${Math.min(i*55,280)}ms`);observer.observe(el);});
    warmLandingCleanup=()=>observer.disconnect();
  } else revealTargets.forEach(el=>el.classList.add('is-visible'));
  const nav=root.querySelector('.warm-nav');
  const onScroll=()=>nav?.classList.toggle('is-scrolled',window.scrollY>24);
  window.addEventListener('scroll',onScroll,{passive:true}); onScroll();
  const move=(e)=>{if(reduced)return;const r=root.getBoundingClientRect();root.style.setProperty('--pointer-x',`${((e.clientX-r.left)/r.width*100).toFixed(2)}%`);root.style.setProperty('--pointer-y',`${((e.clientY-r.top)/r.height*100).toFixed(2)}%`);};
  root.addEventListener('pointermove',move,{passive:true});
  const old=warmLandingCleanup;warmLandingCleanup=()=>{old?.();window.removeEventListener('scroll',onScroll);root.removeEventListener('pointermove',move);};
}

function sidebar(){
  const items=[['home','Dashboard','dashboard'],['file','Applications','applications'],['scale','Instruments','instruments'],['clock','Inspections','inspections'],['shield','Certificates','certificates'],['map','GATC Centres','gatc'],['warning','Risk Command','risk'],['grid','Complaints','complaints'],['route','Reports','reports'],['file','Repairs','repairs']];
  const access=state.currentUser?.access||[];const user=state.currentUser||{name:'Local user',roleLabel:'Workspace'};const initials=user.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  return `<aside class="sidebar ${state.sidebarOpen?'mobile-open':''}">${brand()}<div class="nav-label">${esc(user.workspace||'Workspace')}</div><nav class="side-nav">${items.filter(x=>access.includes(x[2])).map(x=>`<button class="${state.route===x[2]?'active':''}" onclick="navigate('${x[2]}')">${icon(x[0])}<span>${x[1]}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="side-nav settings-row" onclick="navigate('settings')"><span>${icon('user')} Settings</span></button><div class="profile-mini"><div class="avatar">${initials}</div><div><strong>${esc(user.name)}</strong><span>${esc(user.roleLabel)}</span></div></div><button class="sidebar-logout" onclick="logoutUser()">${icon('logout')} Sign out</button></div></aside>`;
}
