function instrumentImage(type){const t=String(type||'').toLowerCase();if(t.includes('fuel')||t.includes('dispenser'))return 'https://akm-img-a-in.tosshub.com/businesstoday/images/story/202008/petrol_diesel_660_100820083631.jpg';if(t.includes('water'))return 'https://cpimg.tistatic.com/07303068/b/5/Amr-Compatible-Water-Meter.jpg';if(t.includes('volumetric')||t.includes('measure'))return 'https://www.metrologiaaplicada.com/web/image/product.template/13211/image_1024?unique=52adcc4';if(t.includes('platform'))return 'https://digital-scales-company.co.uk/3017-large_default/brecknell-dcsb-1500mm-x-1500mm-platform-scale.jpg';if(t.includes('weigh'))return 'https://rukminim2.flixcart.com/image/416/416/l0zm64w0/weighing-scale/p/z/y/30kg-digital-weighing-scale-for-home-and-shop-stainless-steel-original-imagcnqmt69stkct.jpeg?q=70';return 'assets/measurement-instrument.png';}
function instrumentImageSource(type){const t=String(type||'').toLowerCase();if(t.includes('fuel')||t.includes('dispenser'))return 'Business Today';if(t.includes('water'))return 'Water Meters India';if(t.includes('volumetric')||t.includes('measure'))return 'Metrología Aplicada';if(t.includes('platform'))return 'Digital Scales Company';if(t.includes('weigh'))return 'Flipkart / Microtech';return 'Veriq registry';}
function instrumentMode(type){const t=String(type||'').toLowerCase();if(t.includes('fuel')||t.includes('dispenser'))return ['FUEL','FLOW','DISPENSE'];if(t.includes('water'))return ['WATER','VOLUME','AMR'];if(t.includes('platform'))return ['MASS','LOAD','PLATFORM'];if(t.includes('weigh'))return ['MASS','PRECISION','WEIGH'];return ['VOLUME','MEASURE','FIELD'];}
async function instruments(){const rows=await api.instruments();const verified=rows.filter(r=>r.status==='Verified').length;const high=rows.filter(r=>r.risk?.score>=75).length;const due=rows.filter(r=>r.status==='Expiring Soon'||r.status==='Overdue').length;const avg=rows.length?Math.round(rows.reduce((a,r)=>a+(r.risk?.score||0),0)/rows.length):0;return `<div class="page instruments-page"><div class="page-head instruments-head"><div><div class="eyebrow page-eyebrow">LIVE INSTRUMENT REGISTRY / 2026</div><h1>Instrument Command Deck</h1></div><button class="btn btn-primary page-action" onclick="openDrawer('instrument')">${icon('plus')} Register instrument</button></div><section class="instrument-command-deck"><div class="deck-copy"><span class="deck-kicker"><i></i> VERIQ FIELD REGISTRY</span><h2>Every measurement<br><em>has a trace.</em></h2><p>Real instrument imagery, live identity signals and verification intelligence — without losing the clarity of a government-grade registry.</p><div class="deck-actions"><button class="deck-chip active" onclick="document.querySelector('.instrument-gallery')?.scrollIntoView({behavior:'smooth'})">Explore registry ${icon('arrow')}</button><span>LIVE SYNC <b>${rows.length}</b></span><span>PASSPORTS <b>${rows.length}</b></span></div></div><div class="deck-orbit"><div class="orbit-ring r1"></div><div class="orbit-ring r2"></div><div class="orbit-core"><span>MT</span><small>REGISTRY</small></div><div class="orbit-node n1">ID</div><div class="orbit-node n2">QR</div><div class="orbit-node n3">SIG</div></div><div class="deck-metrics"><div><span>VERIFIED</span><strong>${verified}</strong><small>trusted instruments</small></div><div><span>DUE / OVERDUE</span><strong>${due}</strong><small>needs attention</small></div><div><span>RISK INDEX</span><strong>${avg}</strong><small>registry average</small></div><div><span>HIGH RISK</span><strong>${high}</strong><small>priority records</small></div></div></section><div class="instrument-section-head"><div><span>01 / PHYSICAL REGISTRY</span><h2>Registered instruments</h2></div><div class="registry-legend"><span><i class="live-dot"></i> LIVE</span><span>Passport-linked</span><span>Risk-aware</span></div></div><div class="filters instrument-filters"><input class="filter" placeholder="Search ID, serial number or model..." oninput="filterTable(this.value)"><select class="filter" onchange="filterStatus(this.value)"><option>All statuses</option><option>Verified</option><option>Expiring Soon</option><option>Overdue</option><option>Inspection Failed</option></select></div><section class="instrument-gallery">${rows.map((r,i)=>{const img=instrumentImage(r.type),modes=instrumentMode(r.type);return `<article class="instrument-card instrument-card-new ${statusClass(r.status)}" style="--card-index:${i}"><div class="instrument-image"><img src="${img}" alt="${esc(r.type)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='assets/measurement-instrument.png'"><span class="instrument-number">0${i+1}</span></div><div class="instrument-card-body"><div class="instrument-card-title"><div><div class="instrument-type-row"><span class="instrument-type">${esc(r.type)}</span><span class="instrument-body-status ${statusClass(r.status)}">${esc(r.status)}</span></div><h3>${esc(r.id)}</h3><p>${esc(r.make)} · ${esc(r.model)}</p></div><div class="instrument-risk-ring"><strong>${r.risk?.score??0}</strong><span>RISK</span></div></div><div class="instrument-meta"><span><small>SERIAL</small><b>${esc(r.serial)}</b></span><span><small>LOCATION</small><b>${esc(r.location)}</b></span><span><small>NEXT CHECK</small><b>${fmtDate(r.nextDue)}</b></span></div><div class="instrument-mode-row">${modes.map(x=>`<span>${x}</span>`).join('')}<span class="passport-live"><i></i> PASSPORT LINKED</span></div><button class="instrument-view" onclick="openInstrument('${esc(r.id)}')">Open passport ${icon('arrow')}</button></div></article>`;}).join('')}</section></div>`;}
async function instrumentDetail(){const r=await api.instrument(state.selectedInstrument);return `<div class="page"><div class="page-head"><div><p style="margin-bottom:8px"><button class="btn btn-ghost btn-small" onclick="navigate('instruments')">← Instruments</button></p><h1>Instrument passport</h1></div><div class="page-actions"><button class="btn btn-light" onclick="openDrawer('complaint',true)">Report issue</button><button class="btn btn-light" onclick="openDrawer('relocate')">Update location</button><button class="btn btn-light" onclick="openDrawer('repair')">Record repair</button><button class="btn btn-primary" onclick="openDrawer('application')">${icon('plus')} Re-verify</button></div></div><div class="detail-grid"><section class="panel"><div class="instrument-hero"><div class="big-instrument">${icon('scale')}</div><div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><h2>${esc(r.id)}</h2><span class="status ${statusClass(r.status)}">${esc(r.status)}</span><span class="status ${statusClass(r.risk.priority)}">Risk ${r.risk.score}</span></div><p>${esc(r.type)} · ${esc(r.make)} ${esc(r.model)}</p><span style="font-size:10px;color:#927f70">Serial number · ${esc(r.serial)}</span></div></div><div class="detail-tabs">${['Overview','Verification History','Inspections','Certificates','Repairs','Complaints','Risk','Audit'].map(t=>`<button class="${state.instrumentTab===t?'active':''}" onclick="state.instrumentTab='${t}';render()">${t}</button>`).join('')}</div>${instrumentTabContent(r)}</section><aside><section class="panel side-card"><div class="panel-head"><h3>Trust status</h3><span>${r.status}</span></div><span class="status ${statusClass(r.status)}">${esc(r.status)}</span><div class="risk-callout"><div class="risk-number">${r.risk.score}</div><div><strong>${esc(r.risk.priority)} priority</strong><span>${esc(r.risk.recommendedAction)}</span></div></div><div class="panel" style="padding:12px;grid-column:1/-1"><strong>Predictive Trust Model</strong><p style="margin:6px 0 0">${r.risk.mlAvailable?`ML probability <b>${Math.round((r.risk.mlProbability||0)*100)}%</b> · model ${esc(r.risk.mlModelVersion)}`:'ML model unavailable'} · Advisory only.</p></div><div class="qr-box"><div class="qr-placeholder" data-qr="${esc(r.certificates?.[0]?.id||'')}"></div><small>Scan the live certificate</small></div><button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="openDrawer('verify')">Open verification</button></section><section class="panel side-card"><div class="panel-head"><h3>Next action</h3></div><div style="padding:12px;background:#f4ede4;border-radius:12px"><span style="color:#806e61;font-size:9px">NEXT VERIFICATION</span><strong style="display:block;margin-top:5px">${fmtDate(r.nextDue)}</strong></div><div class="mini-factor-list">${r.risk.factors.slice(0,4).map(f=>`<div><span>${esc(f.label)}</span><b>+${f.points}</b></div>`).join('')}</div></section></aside></div></div>`;}
function instrumentTabContent(r){if(state.instrumentTab==='Overview')return `<div class="spec-grid">${[['Type',r.type],['Manufacturer',r.make],['Model',r.model],['Serial number',r.serial],['Capacity',r.capacity],['Accuracy class',r.accuracyClass],['Rule package',r.rule?.id],['Installation',fmtDate(r.installationDate)],['Location',r.location],['Current status',r.status]].map(s=>`<div class="spec"><span>${esc(s[0])}</span><strong>${esc(s[1])}</strong></div>`).join('')}</div><section class="trust-chain-panel"><div class="trust-chain-title"><span>Evidence-backed trust chain</span><small>Rule version ${esc(r.rule?.version||'2026.1')}</small></div><div class="trust-chain">${['Instrument identity','Applicable rule','Inspection evidence','Digital signature','Public certificate'].map((x,i)=>`<div><b>0${i+1}</b><span>${x}</span></div>`).join('')}</div></section>`;
  if(state.instrumentTab==='Verification History')return `<div class="timeline">${(r.certificates||[]).map((c,i)=>`<div class="timeline-row"><div class="timeline-date">${fmtDate(c.issuedAt)}</div><div class="timeline-dot"></div><div class="timeline-content"><strong>${c.id} · ${c.status}</strong><span>Valid through ${c.validToLabel} · Signature ${c.signature.slice(0,12)}…</span><button class="btn btn-light btn-small" style="margin-top:8px" onclick="openCertificate('${c.id}')">Open certificate</button></div></div>`).join('')||'<div class="empty-state"><h3>No certificates yet</h3></div>'}</div>`;
  if(state.instrumentTab==='Inspections')return `<div class="activity-list">${(r.inspections||[]).map(i=>`<div class="activity"><div class="activity-icon">${icon('camera')}</div><div><strong>${i.id} · ${i.result||i.status}</strong><span>${fmtDate(i.createdAt||i.slot)} · ${i.evidence?.length||0} evidence items · ${i.gps?'GPS captured':'GPS not captured'}</span></div><button class="btn btn-light btn-small" onclick="openInspection('${i.id}')">View</button></div>`).join('')||'<div class="empty-state"><h3>No inspection records</h3></div>'}</div>`;
  if(state.instrumentTab==='Certificates')return `<div class="activity-list">${(r.certificates||[]).map(c=>`<div class="activity"><div class="activity-icon">${icon('shield')}</div><div><strong>${c.id}</strong><span>${c.status} · ${c.validToLabel}</span></div><button class="btn btn-light btn-small" onclick="openCertificate('${c.id}')">View</button></div>`).join('')||'<div class="empty-state"><h3>No certificates</h3></div>'}</div>`;
  if(state.instrumentTab==='Repairs')return `<div class="activity-list">${(r.repairs||[]).map(x=>`<div class="activity"><div class="activity-icon">${icon('refresh')}</div><div><strong>${esc(x.id)} · ${esc(x.repairer)}</strong><span>${fmtDate(x.date)} · ${esc(x.reason)}</span></div><span class="status warning">Recorded</span></div>`).join('')||'<div class="empty-state"><h3>No repairs</h3></div>'}</div>`;
  if(state.instrumentTab==='Complaints')return `<div class="activity-list">${(r.complaints||[]).map(c=>`<div class="activity"><div class="activity-icon ${statusClass(c.status)}">${icon('warning')}</div><div><strong>${c.id} · ${c.category}</strong><span>${c.description}</span></div><span class="status ${statusClass(c.status)}">${c.status}</span></div>`).join('')||'<div class="empty-state"><h3>No complaints</h3></div>'}</div>`;
  if(state.instrumentTab==='Risk')return `<div class="risk-detail-grid"><div class="risk-callout"><div class="risk-number">${r.risk.score}</div><div><strong>${esc(r.risk.priority)} priority</strong><span>${esc(r.risk.recommendedAction)}</span></div></div><div class="panel" style="padding:12px;grid-column:1/-1"><strong>Predictive Trust Model</strong><p style="margin:6px 0 0">${r.risk.mlAvailable?`ML probability <b>${Math.round((r.risk.mlProbability||0)*100)}%</b> · model ${esc(r.risk.mlModelVersion)}`:'ML model unavailable'} · Advisory only.</p></div><div class="mini-factor-list">${r.risk.factors.map(f=>`<div><span>${esc(f.label)}</span><b>+${f.points}</b></div>`).join('')}</div><div class="panel" style="padding:16px"><strong>Scan and lifecycle signals</strong><p style="margin:6px 0 0">${r.scanEvents?.length||0} public verification events · ${r.complaints?.length||0} complaints · ${r.repairs?.length||0} repairs</p><div class="drawer-actions-inline" style="margin-top:12px"><button class="btn btn-light btn-small" onclick="openFraudGraph('${esc(r.id)}')">Evidence graph</button>${r.certificates?.[0]?`<button class="btn btn-light btn-small" onclick="openScanAnalytics('${esc(r.certificates[0].id)}')">Scan analytics</button>`:''}</div></div></div>`;
  return `<div class="activity-list">${(r.audit||[]).map(a=>`<div class="activity"><div class="activity-icon">${icon('file')}</div><div><strong>${esc(a.action.replace(/_/g,' '))}</strong><span>${fmtDate(a.timestamp)} · ${esc(a.actorName)} · ${esc(a.entityType)}</span></div><small class="mono-cell">${esc(a.hash.slice(0,14))}…</small></div>`).join('')||'<div class="empty-state"><h3>No audit events</h3></div>'}</div>`;}

async function applications(){const rows=await api.applications();const counts={all:rows.length,pending:rows.filter(r=>r.status==='Under Review').length,scheduled:rows.filter(r=>r.status==='Scheduled').length,approved:rows.filter(r=>r.status==='Approved').length};return `<div class="page"><div class="page-head"><div><div class="eyebrow page-eyebrow">Compliance workflow</div><h1>Applications</h1></div><button class="btn btn-primary" onclick="openDrawer('application')">${icon('plus')} New application</button></div><section class="application-summary"><div class="application-summary-main"><span class="summary-label">APPLICATION QUEUE</span><strong>${counts.all}</strong><span>records in the current workspace</span></div><div class="application-metrics"><div><b>${counts.pending}</b><span>Under review</span></div><div><b>${counts.scheduled}</b><span>Scheduled</span></div><div><b>${counts.approved}</b><span>Approved</span></div></div></section><section class="panel application-workspace"><div class="workspace-toolbar"><div class="workspace-tabs"><button class="active">All applications <span>${counts.all}</span></button></div><div class="workspace-tools"><input class="filter application-search" placeholder="Search ID, applicant or instrument..." oninput="filterTable(this.value)"></div></div><div class="application-table-wrap"><table class="data-table application-table"><thead><tr><th>Application</th><th>Applicant</th><th>Instrument</th><th>Request</th><th>Status</th><th>Fee</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="record-id"><strong>${esc(r.id)}</strong><span>${esc(r.currentStage||'Submitted')}</span></div></td><td><strong class="cell-primary">${esc(r.applicant)}</strong></td><td><span class="mono-cell">${esc(r.instrumentId)}</span></td><td>${esc(r.type)}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td><td><span class="status ${statusClass(r.feeStatus)}">${esc(r.feeStatus||'Pending')}</span></td><td><button class="btn btn-light btn-small" onclick="openApplication('${esc(r.id)}')">View</button></td></tr>`).join('')}</tbody></table></div></section></div>`;}

async function inspections(){const rows=await api.inspections();return `<div class="page"><div class="page-head"><div><div class="eyebrow page-eyebrow">Field verification</div><h1>Inspections</h1></div><div class="page-actions"><button class="btn btn-light" onclick="syncOffline()">${icon('refresh')} Sync offline</button><button class="btn btn-primary" onclick="openDrawer('inspection')">${icon('plus')} Start inspection</button></div></div><div class="three-grid"><article class="info-card"><div class="big-icon">${icon('clock')}</div><h3>Scheduled</h3><p>${rows.filter(r=>r.status==='Scheduled').length} inspections waiting for field action.</p></article><article class="info-card"><div class="big-icon">${icon('camera')}</div><h3>Evidence-first</h3><p>Photos, GPS, readings, timestamp and device metadata stay attached to the inspection.</p></article><article class="info-card"><div class="big-icon">${icon('route')}</div><h3>Offline ready</h3><p><span id="offline-count">${getOfflineDraftMeta().length}</span> locally queued inspection draft(s).</p></article></div><section class="panel table-panel"><div class="panel-head"><div><h3>Inspection queue</h3><span>Click an inspection to open the field workspace.</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Instrument</th><th>Location</th><th>Officer</th><th>Slot</th><th>Status</th><th>Result</th></tr></thead><tbody>${rows.map(r=>`<tr onclick="openInspection('${esc(r.id)}')" style="cursor:pointer"><td><strong>${esc(r.id)}</strong></td><td>${esc(r.instrumentId)}</td><td>${esc(r.location)}</td><td>${esc(r.officer)}</td><td>${esc(r.slot)}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td><td><span class="status ${statusClass(r.result||'Pending')}">${esc(r.result||'Pending')}</span></td></tr>`).join('')}</tbody></table></div></section></div>`;}

async function inspectionDetail(){
  const r=await api.inspection(state.selectedInspection);state.currentInspectionRule=r.rule;state.currentInspection=r;
  const resultDone=r.status==='Completed';
  const standardText=r.standardId?`Standard ${r.standardId}`:'No reference standard attached';
  const failAction=state.currentUser?.role==='business'&&r.status==='Completed'&&r.result==='FAIL'?`<button class="btn btn-primary" onclick="requestReinspection('${esc(r.id)}')">Request re-inspection</button>`:'';
  return `<div class="page"><div class="page-head"><div><p style="margin-bottom:8px"><button class="btn btn-ghost btn-small" onclick="navigate('inspections')">← Inspections</button></p><h1>Field verification workspace</h1></div><div class="page-actions"><span class="status ${statusClass(r.status)}">${esc(r.status)}</span>${failAction}${state.currentUser?.role==='business'&&r.status==='Completed'?`<button class="btn btn-light" onclick="state.selectedFeedbackInspection='${esc(r.id)}';state.selectedComplaint='';openDrawer('feedback')">Feedback</button>`:''}</div></div>
  <div class="detail-grid"><section class="panel"><div class="inspection-header-grid"><div><span class="eyebrow page-eyebrow">Instrument identity</span><h2>${esc(r.instrument.id)}</h2><p>${esc(r.instrument.type)} · ${esc(r.instrument.make)} ${esc(r.instrument.model)}</p><div class="spec-grid compact-grid">${[['Serial',r.instrument.serial],['Capacity',r.instrument.capacity],['Accuracy',r.instrument.accuracyClass],['Rule',r.rule.version],['Reference standard',standardText]].map(x=>`<div class="spec"><span>${x[0]}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div></div><div class="risk-callout"><div class="risk-number">${r.risk.score}</div><div><strong>${r.risk.priority} priority</strong><span>${esc(r.risk.recommendedAction)}</span></div></div></div>
  ${resultDone?`<section class="panel" style="margin:14px 0;padding:16px"><div class="panel-head"><div><h3>Submitted evidence</h3><span>${r.result||'—'} · ${esc(r.signatureAlgorithm||'Ed25519')}</span></div></div><div class="activity-list">${(r.evidence||[]).map(e=>`<div class="activity"><div class="activity-icon">${icon('file')}</div><div><strong>${esc(e.name||'Evidence')}</strong><span>${esc(e.type||'file')} · ${esc(e.hash?.slice(0,20)||'')}…</span></div>${e.id?`<a class="btn btn-light btn-small" href="/api/evidence/${encodeURIComponent(e.id)}" target="_blank">Open</a>`:''}</div>`).join('')||'<div class="empty-state compact"><p>No stored evidence.</p></div>'}</div></section>`:''}
  <div class="field-step-grid"><section><div class="panel-head"><h3>1. Identity checks</h3></div><div class="checklist">${[['Digital QR record','Server-side record lookup'],['Serial number','Physical serial must match registry'],['Rule package',`${r.rule.version} · ${r.rule.mpePercent}% MPE demo parameter`],['Jurisdiction','Location consistency against registered premises']].map((x,i)=>`<label class="check-row"><input type="checkbox" ${i<1?'checked':''}><span><b>${x[0]}</b><small>${x[1]}</small></span></label>`).join('')}</div></section><section><div class="panel-head"><h3>2. Physical test</h3></div>${resultDone?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Test</th><th>Expected</th><th>Observed</th><th>Error</th><th>MPE</th><th>Result</th></tr></thead><tbody>${(r.testReadings||[]).map(t=>`<tr><td>${esc(t.test)}</td><td>${esc(t.expected)}</td><td>${esc(t.observed)}</td><td>${esc(t.error)}</td><td>${esc(t.mpe)}</td><td><span class="status ${statusClass(t.pass?'PASS':'FAIL')}">${t.pass?'PASS':'FAIL'}</span></td></tr>`).join('')}</tbody></table></div>`:`<form id="inspection-form" onsubmit="submitInspection(event)"><div class="test-reading-grid">${r.rule.steps.map((step,i)=>`<div class="test-row"><div><span>${String(i+1).padStart(2,'0')}</span><label>${esc(step)}</label></div><input class="inspection-expected" type="number" step="0.001" value="${i===1?100:''}" placeholder="Reference"><input class="inspection-observed" type="number" step="0.001" placeholder="Observed"></div>`).join('')}</div><div class="form-grid"><div class="field"><label>Captured physical serial</label><div class="input-action-row"><input id="captured-serial" value="${esc(r.instrument.serial)}" required><button type="button" class="btn btn-light btn-small" onclick="scanInspectionQr('${esc(r.id)}')">${icon('shield')} Scan QR</button></div><small class="field-help">Scan the certificate sticker and compare its live trust record with this inspection.</small></div><div class="field"><label>Final result</label><select id="inspection-result"><option>PASS</option><option>FAIL</option></select></div><div class="field"><label>Inspection note</label><input id="inspection-note" placeholder="Officer observation"></div><div class="field full"><label>Evidence files</label><input id="evidence-files" type="file" accept="image/*,.pdf,.txt,.csv" capture="environment" multiple onchange="previewEvidence(this)"><div id="evidence-list" class="evidence-list"></div></div><div class="field"><label>GPS</label><div class="input-action-row"><input id="gps-value" placeholder="Permission-based GPS"><button type="button" class="btn btn-light btn-small" onclick="captureGps()">${icon('pin')} Capture</button></div></div><div class="field"><label>Offline mode</label><label class="switch-line"><input id="offline-mode" type="checkbox"><span>Save locally and sync later</span></label></div></div><div class="drawer-actions-inline"><button type="button" class="btn btn-light" onclick="saveOfflineDraft('${esc(r.id)}')">Save offline draft</button><button class="btn btn-primary" type="submit">${icon('check')} Submit verification</button></div></form>`}</section></div></section><aside><section class="panel side-card"><div class="panel-head"><h3>Evidence capsule</h3><span>${resultDone?'Stored':'Preview'}</span></div><div class="evidence-summary"><div><b>Rule</b><span>${esc(r.rule.id)}</span></div><div><b>MPE</b><span>${esc(r.rule.mpePercent)}%</span></div><div><b>Standard</b><span>${esc(standardText)}</span></div><div><b>Device</b><span>${esc(r.deviceId||'WEB-FIELD-DEVICE')}</span></div><div><b>GPS</b><span>${r.gps?`${Number(r.gps.lat).toFixed(4)}, ${Number(r.gps.lng).toFixed(4)}`:'Pending'}</span></div><div><b>Signature</b><span>${resultDone?esc(r.signatureAlgorithm||'Ed25519'):'Generated on submit'}</span></div></div></section><section class="panel side-card"><div class="panel-head"><h3>History</h3></div><div class="mini-factor-list">${r.risk.factors.slice(0,5).map(f=>`<div><span>${esc(f.label)}</span><b>+${f.points}</b></div>`).join('')}</div></section></aside></div></div>`;
}

async function certificates(){const rows=await api.certificates();return `<div class="page"><div class="page-head"><div><div class="eyebrow page-eyebrow">Digital certificate register</div><h1>Certificates</h1></div><button class="btn btn-primary" onclick="openDrawer('verify')">${icon('shield')} Public verification</button></div><div class="certificate-summary-grid"><article class="certificate-summary"><span>Issued records</span><strong>${rows.length}</strong><small>Certificates in registry</small></article><article class="certificate-summary"><span>Active</span><strong>${rows.filter(c=>c.status==='Active').length}</strong><small>Currently valid</small></article><article class="certificate-summary"><span>Revoked</span><strong>${rows.filter(c=>c.revokedAt).length}</strong><small>Blocked certificates</small></article><article class="certificate-summary"><span>Public checks</span><strong>${(await api.audit()).filter(a=>a.action==='PUBLIC_QR_VERIFY').length}</strong><small>Recorded trust checks</small></article></div><section class="panel table-panel"><div class="panel-head"><div><h3>Issued verification certificates</h3><span>Open a record to inspect the trust chain.</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Certificate</th><th>Instrument</th><th>Issued</th><th>Valid until</th><th>Status</th><th>Integrations</th></tr></thead><tbody>${rows.map(r=>`<tr onclick="openCertificate('${esc(r.id)}')" style="cursor:pointer"><td><strong>${esc(r.id)}</strong><small class="table-subtext">Signature ${esc(r.signature.slice(0,12))}…</small></td><td>${esc(r.instrumentId)}</td><td>${fmtDate(r.issuedAt)}</td><td>${esc(r.validToLabel)}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td><td><span class="status ${r.digilockerStatus?.includes('Published')?'verified':'pending'}">${esc(r.digilockerStatus)}</span></td></tr>`).join('')}</tbody></table></div></section></div>`;}

async function gatc(){const rows=await api.gatc();return `<div class="page gatc-page"><div class="page-head"><div><div class="eyebrow page-eyebrow">Test centre network</div><h1>GATC Centres</h1></div>${state.currentUser?.role==='admin'?`<button class="btn btn-primary page-action" onclick="openDrawer('gatc')">${icon('plus')} Add centre</button>`:''}</div><div class="gatc-overview"><div><span>NETWORK</span><strong>${rows.length}</strong><small>approved / listed centres</small></div><div><span>OPEN CAPACITY</span><strong>${rows.reduce((a,r)=>a+Number(r.availableSlots||0),0)}</strong><small>verification slots</small></div><div><span>REFERENCE STANDARDS</span><strong>${rows.reduce((a,r)=>a+(r.standards?.length||0),0)}</strong><small>traceable standards</small></div></div><div class="gatc-layout"><section class="panel gatc-network-panel"><div class="panel-head"><div><h3>Centre network</h3><span>Operational capacity and jurisdiction</span></div><span class="panel-count">${rows.length} centres</span></div><div class="gatc-centre-list">${rows.map(r=>`<article class="gatc-centre-card"><div class="gatc-centre-main"><div class="gatc-centre-icon">${icon('map')}</div><div class="gatc-centre-copy"><div class="gatc-centre-title"><h3>${esc(r.name)}</h3><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></div><p>${esc(r.city)}, ${esc(r.state)} · ${r.distanceKm ?? '—'} km away</p><div class="gatc-centre-metrics"><span><b>${r.categories}</b> categories</span><span><b>${r.availableSlots}</b> open slots</span><span><b>${r.capacity}</b> capacity</span></div></div></div>${state.currentUser?.role==='admin'?`<div class="gatc-action-rail"><button class="btn btn-light btn-small" onclick="state.selectedGatc='${esc(r.id)}';openDrawer('standard')">Add standard</button><button class="btn btn-light btn-small" onclick="toggleGatcStatus('${esc(r.id)}','${r.status==='Suspended'?'Available':'Suspended'}')">${r.status==='Suspended'?'Activate':'Suspend'}</button><button class="btn btn-light btn-small" onclick="editGatc('${esc(r.id)}','${esc(r.name)}','${esc(r.city)}','${esc(r.state)}',${r.categories},${r.capacity},${r.availableSlots},${r.lat??''},${r.lng??''})">Edit</button><button class="btn btn-light btn-small" onclick="editGatcCapacity('${esc(r.id)}',${r.capacity},${r.availableSlots})">Capacity</button></div>`:''}</article>`).join('')}</div></section><section class="panel gatc-standards-panel"><div class="panel-head"><div><h3>Reference standards</h3><span>Calibration and traceability</span></div></div><div class="gatc-standard-list">${rows.flatMap(r=>r.standards.map(s=>`<article class="gatc-standard-card"><div class="gatc-standard-icon">${icon('shield')}</div><div><strong>${esc(s.name)}</strong><span>${esc(r.name)}</span><small>Calibration due ${fmtDate(s.calibrationDue)} · ${esc(s.certificateId||'No certificate')}</small></div><span class="status ${statusClass(s.status)}">${esc(s.status)}</span>${state.currentUser?.role==='admin'||(state.currentUser?.role==='gatc'&&state.currentUser?.gatcId===r.id)?`<button class="btn btn-light btn-small" onclick="toggleStandardStatus('${esc(r.id)}','${esc(s.id)}','${s.status==='Calibrated'?'Expired':'Calibrated'}')">${s.status==='Calibrated'?'Mark expired':'Calibrate'}</button>`:''}</article>`)).join('')||'<div class="empty-state compact"><p>No reference standards registered.</p></div>'}</div></section></div></div>`;}
async function riskPage(){
  const [rows,fraud,model]=await Promise.all([api.risk(),api.fraud(),api.riskModel()]);
  const mlRows=rows.filter(x=>x.risk.mlAvailable);
  const avg=mlRows.length?Math.round(mlRows.reduce((a,x)=>a+(x.risk.mlScore||0),0)/mlRows.length):0;
  return `<div class="page"><div class="page-head"><div><div class="eyebrow page-eyebrow">Risk intelligence · ML enabled</div><h1>Predictive Trust Command</h1></div><div class="page-actions"><button class="btn btn-light" onclick="recomputeRiskModel()">${icon('refresh')} Recompute ML signals</button><button class="btn btn-primary" onclick="navigate('inspections')">Open inspection queue ${icon('arrow')}</button></div></div>
  <div class="three-grid"><article class="info-card"><div class="big-icon">${icon('warning')}</div><h3>${rows.filter(x=>x.risk.priority==='HIGH').length} high priority</h3><p>Hybrid priority after deterministic checks and ML prediction.</p></article><article class="info-card"><div class="big-icon">${icon('shield')}</div><h3>${fraud.filter(x=>!x.resolved).length} open trust signals</h3><p>Rule-based and ML-generated signals require authorized human review.</p></article><article class="info-card"><div class="big-icon">${icon('route')}</div><h3>${model.available?'ML '+avg+'/100':'ML unavailable'}</h3><p>${model.available?`${esc(model.algorithm)} · ${model.trainingRows} prototype training rows.`:'Run the training script to generate the model artifact.'}</p></article></div>
  <section class="panel table-panel"><div class="panel-head"><div><h3>Predictive inspection queue</h3><span>Hybrid score = 55% deterministic lifecycle risk + 45% ML prediction. ML is advisory only.</span></div><span class="status ${model.available?'verified':'danger'}">${model.available?esc(model.version):'MODEL NOT LOADED'}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Instrument</th><th>Hybrid</th><th>ML probability</th><th>Priority</th><th>Why the model flagged it</th><th>Action</th></tr></thead><tbody>${rows.map(x=>{const rf=(x.risk.mlFactors||[]).slice(0,2).map(f=>`${f.feature} ${f.contribution>=0?'+':''}${f.contribution.toFixed(2)}`).join(' · ');return `<tr><td><strong>${esc(x.instrument.id)}</strong><small class="table-subtext">${esc(x.instrument.type)} · ${esc(x.instrument.location)}</small></td><td><strong>${x.risk.score}/100</strong><small class="table-subtext">base ${x.risk.deterministicScore}</small></td><td>${x.risk.mlAvailable?`${Math.round((x.risk.mlProbability||0)*100)}%`:'—'}</td><td><span class="status ${statusClass(x.risk.priority)}">${x.risk.priority}</span></td><td>${esc(rf||'No ML contribution available')}</td><td><button class="btn btn-light btn-small" onclick="openInstrument('${esc(x.instrument.id)}')">Passport</button> <button class="btn btn-light btn-small" onclick="openFraudGraph('${esc(x.instrument.id)}')">Graph</button></td></tr>`}).join('')}</tbody></table></div></section>
  <section class="panel table-panel"><div class="panel-head"><div><h3>Trust / anomaly signals</h3><span>ML-generated predictive signals are intentionally advisory and never auto-approve or auto-reject an instrument.</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Signal</th><th>Instrument</th><th>Severity</th><th>Reason</th><th></th></tr></thead><tbody>${fraud.map(f=>`<tr><td><strong>${esc(f.id)}</strong><small class="table-subtext">${esc(f.type)}</small></td><td>${esc(f.instrumentId)}</td><td><span class="status ${statusClass(f.severity)}">${esc(f.severity)}</span></td><td>${esc(f.description)}</td><td>${!f.resolved?`<button class="btn btn-light btn-small" onclick="resolveFraud('${esc(f.id)}')">Resolve</button>`:'<span class="status verified">Resolved</span>'}</td></tr>`).join('')}</tbody></table></div></section>
  <section class="panel" style="padding:16px"><div class="panel-head"><div><h3>Model transparency</h3><span>Training and deployment boundary</span></div></div><div class="spec-grid compact-grid">${[['Algorithm',model.algorithm||'—'],['Model version',model.version||'—'],['Training rows',model.trainingRows||'—'],['Features',(model.features||[]).join(', ')],['Training status',model.available?'Loaded':'Not loaded'],['Decision boundary','Advisory · human review required']].map(x=>`<div class="spec"><span>${esc(x[0])}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div></section></div>`;
}
async function recomputeRiskModel(){try{const r=await api.recomputeRisk();showToast(`ML scan complete: ${r.createdSignals} new predictive signal(s).`);render();}catch(e){showToast(e.message);}}

async function reports(){const r=await api.reports();const orbit=[['file','Applications',r.stats.applications,'registry records','teal'],['camera','Inspections',r.stats.inspections,'field events','blue'],['shield','Certificates',r.stats.certificates,'signed records','amber'],['warning','Open complaints',r.stats.complaintsOpen,'public reports','red']];return `<div class="page reports-page"><div class="page-head reports-head"><div><div class="eyebrow page-eyebrow">Operations intelligence · Live registry</div><h1>Reports & Insights</h1></div><button class="btn btn-primary" onclick="downloadCsv(${JSON.stringify(r.topRisk).replace(/</g,'&lt;')},'veriq-risk.csv')">${icon('download')} Export risk</button></div><section class="insight-orbit-panel"><div class="insight-orbit-head"><div><span class="panel-kicker">LIVE SYSTEM PULSE</span><h2>Four signals. One connected picture.</h2><p>Rotate the intelligence ring or select a signal to bring it forward.</p></div><div class="orbit-live"><span></span> LIVE</div></div><div class="insight-orbit-scene"><div class="orbit-glow"></div><div class="insight-orbit" id="insight-orbit">${orbit.map((c,i)=>`<article class="insight-orbit-card ${i===0?'is-active':''}" data-orbit-index="${i}"><div class="orbit-card-top"><span class="orbit-card-icon">${icon(c[0])}</span><span class="orbit-card-state">LIVE</span></div><strong>${c[1]}</strong><b>${c[2]}</b><small>${c[3]}</small><i class="orbit-card-line"></i></article>`).join('')}<div class="orbit-hub"><div class="hub-ring ring-one"></div><div class="hub-ring ring-two"></div><div class="hub-core">${icon('route')}</div></div></div><div class="orbit-auto-note"><span></span><b>LIVE SEQUENCE</b><small>Signals advance automatically</small></div></div></section><div class="kpi-grid dashboard-kpis reports-secondary-kpis">${dashboardKpi('file','Applications',r.stats.applications,'Live','registry','teal')}${dashboardKpi('camera','Inspections',r.stats.inspections,'Live','field events','blue')}${dashboardKpi('shield','Certificates',r.stats.certificates,'Live','signed records','amber')}${dashboardKpi('warning','Open complaints',r.stats.complaintsOpen,'Live','public reports','red')}</div><div class="three-grid"><article class="info-card glass-deep"><div class="big-icon">${icon('grid')}</div><h3>Instrument mix</h3><p>${Object.entries(r.byType).map(([k,v])=>`${esc(k)}: <b>${v}</b>`).join('<br>')}</p></article><article class="info-card glass-deep"><div class="big-icon">${icon('route')}</div><h3>Fraud posture</h3><p>${r.stats.fraudOpen} unresolved anomaly signals are currently attached to the risk layer.</p></article><article class="info-card glass-deep"><div class="big-icon">${icon('shield')}</div><h3>Auditability</h3><p>Every issuance, revocation, complaint and public verification is recorded in the event chain.</p></article></div><section class="panel table-panel glass-deep"><div class="panel-head"><div><h3>Top risk records</h3><span>Use this queue to drive inspection planning.</span></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Instrument</th><th>Score</th><th>Priority</th><th>Recommendation</th></tr></thead><tbody>${r.topRisk.map(x=>`<tr><td>${esc(x.id)}</td><td><strong>${x.score}/100</strong></td><td><span class="status ${statusClass(x.priority)}">${esc(x.priority)}</span></td><td>${esc(x.recommendedAction)}</td></tr>`).join('')}</tbody></table></div></section></div>`;}


