async function pageFor(route){const base=String(route||'').split('/')[0],arg=String(route||'').split('/')[1]||'';switch(base){case'dashboard':return dashboard();case'instruments':return instruments();case'instrument':return instrumentDetail();case'applications':return applications();case'inspections':return inspections();case'inspection':return inspectionDetail();case'certificates':return certificates();case'gatc':return gatc();case'risk':return riskPage();case'complaints':return complaints();case'audit':return audit();case'reports':return reports();case'repairs':return repairs();case'feedback':return feedback();case'rules':return rulesPage();case'users':return usersPage();case'settings':return settingsPage();case'public-verify':return publicVerifyPage(arg);default:return dashboard();}}

function render(){const app=document.getElementById('app');const base=String(state.route||'').split('/')[0];if(base==='public-verify'){app.innerHTML=publicVerifyPage(String(state.route).split('/')[1]||'');renderQrs();return;}if(state.route!=='home'&&!state.currentUser){state.route='home';location.hash='home';}if(state.route!=='home'&&state.currentUser&&!state.currentUser.access.includes(base)){state.route='dashboard';location.hash='dashboard';}if(state.route==='home'){app.innerHTML=landing();initHeroCardLoop();initProcessLoop();initInsightOrbit();initWarmLanding();return;}app.innerHTML=appView('<div class="page"><div class="empty-state"><div class="empty-icon">'+icon('grid')+'</div><h3>Loading workspace</h3><p>Preparing your connected Legal Metrology workspace…</p></div></div>');pageFor(state.route).then(c=>{app.innerHTML=appView(c);if(base==='dashboard')initComplianceMap();if(base==='reports')initInsightOrbit();renderQrs();if(state.drawerOpen)openDrawer(state.drawerOpen,true);}).catch(err=>{console.error(err);app.innerHTML=appView(`<div class="page"><div class="panel empty-state"><div class="empty-icon">${icon('warning')}</div><h3>Something needs attention</h3><p>${esc(err.message||'Data service error')}</p><button class="btn btn-primary" onclick="render()">Retry</button></div></div>`);});}

function navigate(route){state.route=route;state.sidebarOpen=false;location.hash=route;render();window.scrollTo({top:0,behavior:'smooth'});}function openInstrument(id){state.selectedInstrument=id;state.instrumentTab='Overview';navigate('instrument');}function openInspection(id){state.selectedInspection=id;navigate('inspection');}function openApplication(id){state.selectedApplication=id;openDrawer('application-detail');}function toggleSidebar(){state.sidebarOpen=!state.sidebarOpen;render();}
function globalSearch(e){if(e.key!=='Enter')return;const q=e.target.value.trim();if(!q)return;api.search(q).then(r=>{if(r.instruments[0])openInstrument(r.instruments[0].id);else if(r.certificates[0])openCertificate(r.certificates[0].id);else showToast('No matching record found.');}).catch(()=>showToast('Search service unavailable.'));}
function filterTable(v){const q=String(v||'').toLowerCase();document.querySelectorAll('.data-table tbody tr').forEach(tr=>tr.style.display=tr.innerText.toLowerCase().includes(q)?'':'none');}function filterStatus(v){document.querySelectorAll('.instrument-card').forEach(c=>c.style.display=v==='All statuses'||c.innerText.includes(v)?'':'none');}
function showToast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2800);}

let heroCardIndex=0,heroCardTimer=null;function paintHeroCards(){const cards=[...document.querySelectorAll('.hero-feature-card')];cards.forEach(c=>{c.classList.remove('pos-left','pos-center','pos-right','pos-hidden');c.classList.add('is-active');});}function setHeroCard(i){heroCardIndex=0;paintHeroCards();}function shiftHeroCards(d){heroCardIndex=0;paintHeroCards();}function restartHeroCardLoop(){clearInterval(heroCardTimer);heroCardTimer=null;}function initHeroCardLoop(){clearInterval(heroCardTimer);heroCardTimer=null;heroCardIndex=0;paintHeroCards();}function paintInsightOrbit(){const scene=document.getElementById('insight-orbit');const cards=[...document.querySelectorAll('.insight-orbit-card')];if(!scene||!cards.length)return;const active=window.insightOrbitIndex||0;const w=scene.clientWidth;const rx=Math.min(235,Math.max(155,w*.27));const ry=Math.min(125,Math.max(92,w*.13));const depth=Math.min(105,Math.max(70,w*.10));const step=360/cards.length;cards.forEach((card,j)=>{const angle=(j-active)*step*Math.PI/180;const x=Math.sin(angle)*rx;const y=-Math.cos(angle)*ry*.72;const z=Math.cos(angle)*depth;const front=(z+depth)/(depth*2);const scale=.82+front*.18;const opacity=.45+front*.55;card.style.setProperty('--orbit-x',`${x.toFixed(1)}px`);card.style.setProperty('--orbit-y',`${y.toFixed(1)}px`);card.style.setProperty('--orbit-z',`${z.toFixed(1)}px`);card.style.setProperty('--orbit-scale',scale.toFixed(3));card.style.setProperty('--orbit-opacity',opacity.toFixed(3));card.style.setProperty('--orbit-depth',Math.round(z));card.classList.toggle('is-active',j===active);});}
function initInsightOrbit(){clearInterval(window.insightOrbitTimer);if(!document.getElementById('insight-orbit'))return;window.insightOrbitIndex=0;requestAnimationFrame(paintInsightOrbit);if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;window.insightOrbitTimer=setInterval(()=>rotateInsightOrbit(1,false),4200);window.addEventListener('resize',paintInsightOrbit,{passive:true});}
function focusInsightOrbit(i,restart=true){const cards=[...document.querySelectorAll('.insight-orbit-card')];if(!cards.length)return;window.insightOrbitIndex=(i+cards.length)%cards.length;paintInsightOrbit();if(restart){clearInterval(window.insightOrbitTimer);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)window.insightOrbitTimer=setInterval(()=>rotateInsightOrbit(1,false),4200);}}
function rotateInsightOrbit(delta=1,restart=true){focusInsightOrbit((window.insightOrbitIndex||0)+delta,restart);}

let processStepIndex=0,processStepTimer=null;
const processStages=[
  ['01 · Register','Digital identity is created first.'],
  ['02 · Apply','Evidence and application details are connected.'],
  ['03 · Prioritize','Risk and workload shape the next field action.'],
  ['04 · Inspect','Tests, photos, GPS and signatures become evidence.'],
  ['05 · Certify & verify','A live certificate turns the record into public trust.']
];
function paintProcessStep(){
  const steps=[...document.querySelectorAll('.process-step')];
  const progress=document.getElementById('process-progress');
  const title=document.getElementById('process-live-title');
  const copy=document.getElementById('process-live-copy');
  if(!steps.length)return;
  steps.forEach((step,i)=>step.classList.toggle('is-focus',i===processStepIndex));
  if(progress){const pct=(processStepIndex/(steps.length-1))*100;progress.style.width=`${pct}%`;if(document.querySelector('.warm-landing .warm-process-line'))progress.style.height=`${Math.max(8,pct)}%`;}
  if(title)title.textContent=processStages[processStepIndex][0];
  if(copy)copy.textContent=processStages[processStepIndex][1];
}
function setProcessStep(i){
  const n=document.querySelectorAll('.process-step').length||5;
  processStepIndex=(i+n)%n;
  paintProcessStep();
  restartProcessLoop();
}
function restartProcessLoop(){
  clearInterval(processStepTimer);
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  processStepTimer=setInterval(()=>setProcessStep(processStepIndex+1),2500);
}
function initProcessLoop(){
  clearInterval(processStepTimer);
  processStepIndex=0;
  paintProcessStep();
  const track=document.getElementById('process-track');
  if(track) track.onmouseenter=null;
  restartProcessLoop();
}

let complianceMapInstance=null;async function initComplianceMap(){const container=document.getElementById('compliance-map');if(!container)return;try{const d=await api.dashboard();if(!window.maplibregl){const mod=await import('https://unpkg.com/maplibre-gl@5/dist/maplibre-gl.mjs');window.maplibregl=mod;}if(complianceMapInstance){try{complianceMapInstance.remove();}catch(e){}complianceMapInstance=null;}const points=(d.mapPoints||[]).map(p=>({type:'Feature',geometry:{type:'Point',coordinates:[p.lng,p.lat]},properties:{name:p.name,score:p.score,status:p.status}}));const center=points[0]?points[0].geometry.coordinates:[78.9629,22.5937];const map=new maplibregl.Map({container,style:'https://tiles.openfreemap.org/styles/liberty',center,zoom:points.length?5.6:4.15,minZoom:3.2,maxZoom:10,pitch:18,attributionControl:true});complianceMapInstance=map;map.addControl(new maplibregl.NavigationControl({showCompass:true}),'top-right');map.addControl(new maplibregl.ScaleControl({maxWidth:90,unit:'metric'}),'bottom-left');map.on('load',()=>{map.addSource('compliance-points',{type:'geojson',data:{type:'FeatureCollection',features:points},cluster:true,clusterMaxZoom:8,clusterRadius:46});map.addLayer({id:'compliance-clusters',type:'circle',source:'compliance-points',filter:['has','point_count'],paint:{'circle-color':['step',['get','point_count'],'#b58b67',5,'#c49a6b',10,'#9d6655'],'circle-radius':['step',['get','point_count'],18,5,23,10,28],'circle-stroke-width':3,'circle-stroke-color':'rgba(255,255,255,.88)','circle-opacity':.88}});map.addLayer({id:'compliance-cluster-count',type:'symbol',source:'compliance-points',filter:['has','point_count'],layout:{'text-field':['get','point_count_abbreviated'],'text-size':11},paint:{'text-color':'#4a3326'}});map.addLayer({id:'compliance-points',type:'circle',source:'compliance-points',filter:['!',['has','point_count']],paint:{'circle-color':['match',['get','status'],'healthy','#a87850','watch','#b88458','priority','#9b6654','#a99885'],'circle-radius':['interpolate',['linear'],['zoom'],4,5,9,9],'circle-stroke-width':3,'circle-stroke-color':'#fff'}});map.addLayer({id:'compliance-labels',type:'symbol',source:'compliance-points',filter:['!',['has','point_count']],layout:{'text-field':['get','name'],'text-size':10,'text-offset':[0,1.5],'text-anchor':'top'},paint:{'text-color':'#5b4030','text-halo-color':'rgba(255,255,255,.94)','text-halo-width':1.5}});});}catch(e){console.warn(e);container.innerHTML='<div class="map-fallback"><strong>Interactive coverage map</strong><span>Open-source map tiles were unavailable.</span></div>';}}

function field(label,id,value='',type='text',options=[]){if(type==='select')return `<div class="field"><label>${label}</label><select id="${id}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;if(type==='textarea')return `<div class="field"><label>${label}</label><textarea id="${id}" placeholder="${esc(value)}"></textarea></div>`;if(type==='file')return `<div class="field"><label>${label}</label><input id="${id}" type="file" multiple></div>`;return `<div class="field"><label>${label}</label><input id="${id}" type="${type}" ${type==='date'?`value="${value}"`:`placeholder="${esc(value)}"`} required></div>`;}

function drawerMarkup(type){let title='',body='';
  if(type==='instrument'){title='Register instrument';body=`<form onsubmit="submitInstrument(event)"><div class="form-grid">${field('Instrument type','instrumentType','Platform Weighing Scale','select',['Platform Weighing Scale','Weighing Scale','Platform Scale','Fuel Dispenser','Measuring Instrument'])}${field('Manufacturer','manufacturer','Essae Teraoka')}${field('Model','model','ES-15K')}${field('Serial number','serial','WTX-NEW-001')}${field('Capacity','capacity','15 kg')}${field('Accuracy class','accuracyClass','Class III')}${field('Installation date','installationDate','2026-09-29','date')}${field('Location','location','Ludhiana, Punjab')}<div class="field full">${field('Owner note','ownerNote','Optional note','textarea')}</div></div><div class="drawer-actions-inline"><button class="btn btn-primary" type="submit">${icon('check')} Register instrument</button></div></form>`;}
  else if(type==='application'){title='New verification application';body=`<form onsubmit="submitApplication(event)"><div class="form-grid">${field('Application type','applicationType','Verification','select',['Verification','Re-verification'])}${field('Instrument ID','instrumentId',state.selectedInstrument)}${field('Preferred date','preferredDate',new Date(Date.now()+5*86400000).toISOString().slice(0,10),'date')}${field('Centre / location','centre','Field inspection')}<div class="field full">${field('Supporting documents','applicationFiles','','file')}<small class="field-help">Invoice, previous certificate, ownership proof or instrument photos. Files under 2 MB are stored in the local evidence repository.</small></div><div class="field full">${field('Additional note','note','Anything the officer should know…','textarea')}</div></div><div class="payment-card"><span>Fee handling</span><strong>Demo payment · no paid gateway</strong><small>The application is marked paid in the local registry so the rest of the workflow can be tested end-to-end.</small></div><button class="btn btn-primary" style="width:100%;margin-top:18px">Submit & pay ${icon('arrow')}</button></form>`;}
  else if(type==='schedule'){title='Smart scheduling';body=`<form onsubmit="submitSchedule(event)"><div class="form-grid">${field('Application ID','scheduleApp','', 'text')}${field('Inspection date','scheduleDate',new Date(Date.now()+2*86400000).toISOString().slice(0,10),'date')}${field('Time slot','scheduleSlot','09:30')}${field('Officer ID','scheduleOfficer','USR-1002')}${field('GATC centre ID','scheduleCentre','GATC-001')}</div><div id="schedule-recommendation" class="recommendation-box"><button type="button" class="btn btn-light btn-small" onclick="loadRecommendation()">Find best assignment</button></div><div class="drawer-actions-inline"><button class="btn btn-primary" type="submit">Assign & schedule</button></div></form>`;}
  else if(type==='inspection'){title='Start inspection';body=`<form onsubmit="startInspection(event)"><div class="form-grid">${field('Instrument ID','startInstrument',state.selectedInstrument)}${field('Application ID','startApplication',state.selectedApplication||'APP-2026-4561')}${field('Location','startLocation','Use registered premises')}${field('Slot','startSlot','Today · 10:00')}</div><p class="drawer-note">The inspection workspace will load the instrument's rule package, risk factors and checklist.</p><button class="btn btn-primary" style="width:100%">Open field workspace ${icon('arrow')}</button></form>`;}
  else if(type==='complaint'){title='Report unsafe instrument';body=`<form onsubmit="submitPublicComplaint(event)"><div class="form-grid">${field('Instrument ID','complaintInstrument',state.selectedInstrument)}${field('Category','complaintCategory','Incorrect measurement','select',['Incorrect measurement','Broken seal','Suspicious certificate','QR mismatch','Instrument moved','Other'])}<div class="field full">${field('What happened?','complaintDescription','Describe the issue','textarea')}</div>${field('Location','complaintLocation','Registered premises / observed location')}<div class="field full"><label>Evidence photo</label><input id="complaintFiles" type="file" accept="image/*,.pdf" capture="environment" multiple></div></div><button class="btn btn-primary" style="width:100%;margin-top:18px">Submit complaint</button></form>`;}
  else if(type==='verify'){title='Public certificate verification';body=`<div class="verify-drawer"><p>Use the certificate number from the QR or printed certificate. Optionally provide the serial you can see on the physical instrument to detect QR cloning.</p>${field('Certificate ID','verifyCode','e.g. CERT-2026-3421')}${field('Visible serial (optional)','verifySerial','e.g. WTX-239812')}<button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="verifyCode()">${icon('shield')} Verify trust chain</button><div id="verify-result" style="margin-top:14px"></div></div>`;}
  else if(type==='reject'){title='Reject application';body=`<form onsubmit="submitReject(event)"><div class="field"><label>Reason</label><textarea id="rejectReason" required placeholder="State the reason and corrective action."></textarea></div><button class="btn btn-primary" style="width:100%;margin-top:16px">Reject application</button></form>`;}
  else if(type==='relocate'){title='Update instrument location';body=`<form onsubmit="submitRelocation(event)"><div class="form-grid">${field('Instrument ID','relocateInstrument',state.selectedInstrument)}${field('New location','relocateLocation','New premises / city')}${field('Latitude','relocateLat','','number')}${field('Longitude','relocateLng','','number')}</div><button type="button" class="btn btn-light" style="width:100%;margin-top:14px" onclick="captureRelocationGps()">${icon('pin')} Capture current GPS</button><button class="btn btn-primary" style="width:100%;margin-top:14px">Record relocation</button></form>`;}
  else if(type==='repair'){title='Record repair';body=`<form onsubmit="submitRepair(event)"><div class="form-grid">${field('Instrument ID','repairInstrument',state.selectedInstrument)}${field('Repair date','repairDate',new Date().toISOString().slice(0,10),'date')}${field('Repairer','repairer','Authorized service centre') }<div class="field full">${field('Reason','repairReason','Describe the repair','textarea')}</div><div class="field full"><label>Evidence</label><input id="repairFiles" type="file" accept="image/*,.pdf" capture="environment" multiple></div></div><button class="btn btn-primary" style="width:100%;margin-top:18px">Record repair</button></form>`;}
  else if(type==='feedback'){title='Owner feedback';body=`<form onsubmit="submitFeedback(event)"><div class="field"><label>Rating</label><select id="feedbackRating"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Fair</option><option value="2">2 — Poor</option><option value="1">1 — Very poor</option></select></div><div class="field" style="margin-top:14px"><label>Comment</label><textarea id="feedbackComment" placeholder="Tell us about the verification experience."></textarea></div><input type="hidden" id="feedbackComplaintId" value="${esc(state.selectedComplaint||'')}"><input type="hidden" id="feedbackInspectionId" value="${esc(state.selectedFeedbackInspection||'')}"><button class="btn btn-primary" style="width:100%;margin-top:16px">Submit feedback</button></form>`;}
  else if(type==='gatc'){title='Register GATC centre';body=`<form onsubmit="submitGatc(event)"><div class="form-grid">${field('Centre name','gatcName','Precision Metrology Centre')}${field('City','gatcCity','Mohali')}${field('State','gatcState','Punjab')}${field('Categories supported','gatcCategories','10','number')}${field('Capacity','gatcCapacity','20','number')}${field('Open slots','gatcSlots','5','number')}${field('Latitude','gatcLat','30.7046','number')}${field('Longitude','gatcLng','76.7179','number')}</div><button class="btn btn-primary" style="width:100%;margin-top:16px">Register centre</button></form>`;}
  else if(type==='standard'){title='Register reference standard';body=`<form onsubmit="submitStandard(event)"><div class="form-grid">${field('GATC centre ID','standardGatc',state.selectedGatc||'GATC-001')}${field('Standard name','standardName','10 kg OIML test mass')}${field('Calibration due','standardDue',new Date(Date.now()+365*86400000).toISOString().slice(0,10),'date')}${field('Calibration certificate','standardCert','CAL-NEW-001')}</div><button class="btn btn-primary" style="width:100%;margin-top:16px">Register standard</button></form>`;}
  else if(type==='auth'){title=state.authMode==='signup'?'Create your Veriq access':'Sign in to Veriq';const signup=state.authMode==='signup';const roles=[['business','Business / Instrument User','Manage instruments, applications and certificates.'],['lmo','Legal Metrology Officer','Review, schedule, inspect and issue.'],['gatc','GATC Centre','Run tests, evidence and certificate workflows.'],['admin','Administrator','Control risk, audit, users and configuration.']];body=`<div class="auth-experience"><div class="auth-visual-panel"><div class="auth-orb-glow"></div><div class="auth-orb"><div class="auth-orb-core">${icon('shield')}</div><span class="auth-orbit o1"></span><span class="auth-orbit o2"></span></div><span class="auth-visual-kicker">ROLE-AWARE ACCESS</span><h3>One platform.<br><em>Different responsibilities.</em></h3><p>Available screens and server-side actions are controlled by role.</p><div class="auth-access-note"><span>${icon('shield')}</span><div><strong>Authentication ≠ authorization</strong><small>Session identity and role permissions are checked separately.</small></div></div></div><div class="auth-form-panel"><div class="auth-mode-label">${signup?'NEW STAKEHOLDER ACCESS':'SECURE SIGN IN'}</div><div class="auth-role-intro"><h3>${signup?'Who are you registering as?':'Choose your workspace'}</h3><p>Select the stakeholder role for this local test environment.</p></div><div class="auth-role-grid">${roles.map((r,i)=>`<button type="button" class="auth-role-card ${state.authRole===r[0]?'selected':''}" data-role="${r[0]}" onclick="selectAuthRole(this)"><span class="auth-role-icon">${icon(i===0?'user':i===1?'shield':i===2?'map':'grid')}</span><span class="auth-role-copy"><strong>${r[1]}</strong><small>${r[2]}</small></span><i>${icon('arrow')}</i></button>`).join('')}</div><form class="auth-credentials" onsubmit="submitAuth(event)">${signup?`<div class="auth-form-grid"><div class="field"><label>Full name</label><input id="auth-name" required placeholder="e.g. Aarav Mehta"></div><div class="field"><label>Organisation</label><input id="auth-organization" required placeholder="e.g. Mehta Weighing Solutions"></div></div>`:''}<div class="auth-form-grid"><div class="field"><label>Email address</label><input id="auth-email" type="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="auth-password" type="password" minlength="8" required placeholder="At least 8 characters"></div></div><div id="auth-error" class="auth-error"></div><button class="btn btn-primary auth-continue" type="submit">${signup?'Create account':'Sign in'} ${icon('arrow')}</button></form><button type="button" class="auth-switch" onclick="openAuth('${signup?'login':'signup'}')">${signup?'Already have an account? Sign in':'New stakeholder? Create an account'}</button></div></div>`;}
  else if(type==='application-detail'){title='Application detail';body=`<div id="application-detail-body"><p>Loading application…</p></div>`;setTimeout(()=>loadApplicationDetail(),0);}
  return `<div class="drawer-overlay" onclick="if(event.target===this)closeDrawer()"></div><aside class="drawer ${type==='auth'?'auth-drawer':''}"><div class="drawer-head"><h2>${title}</h2><button class="close-btn" onclick="closeDrawer()">${icon('close')}</button></div>${body}</aside>`;
}
function openDrawer(type,fromRender=false){state.drawerOpen=type;const root=document.getElementById('modal-root');root.innerHTML=drawerMarkup(type);requestAnimationFrame(()=>{document.querySelector('.drawer-overlay')?.classList.add('open');document.querySelector('.drawer')?.classList.add('open');});}
function closeDrawer(){state.drawerOpen=false;document.getElementById('modal-root').innerHTML='';}
function openAuth(mode){state.authMode=mode;state.authRole=state.currentUser?.role||'business';openDrawer('auth');}
function selectAuthRole(el){state.authRole=el.dataset.role;document.querySelectorAll('.auth-role-card').forEach(x=>x.classList.toggle('selected',x===el));}
async function submitGatc(e){e.preventDefault();try{await api.createGatc({name:document.getElementById('gatcName').value,city:document.getElementById('gatcCity').value,state:document.getElementById('gatcState').value,categories:Number(document.getElementById('gatcCategories').value),capacity:Number(document.getElementById('gatcCapacity').value),availableSlots:Number(document.getElementById('gatcSlots').value),lat:Number(document.getElementById('gatcLat').value),lng:Number(document.getElementById('gatcLng').value)});closeDrawer();showToast('GATC centre registered.');render();}catch(err){showToast(err.message);}}
async function submitStandard(e){e.preventDefault();try{await api.createStandard(document.getElementById('standardGatc').value,{name:document.getElementById('standardName').value,calibrationDue:document.getElementById('standardDue').value,certificateId:document.getElementById('standardCert').value,status:'Calibrated'});closeDrawer();showToast('Reference standard registered.');render();}catch(err){showToast(err.message);}}
async function submitAuth(e){e.preventDefault();const error=document.getElementById('auth-error');if(error)error.textContent='';const signup=state.authMode==='signup';const p={role:state.authRole,email:document.getElementById('auth-email').value.trim(),password:document.getElementById('auth-password').value};if(signup){p.name=document.getElementById('auth-name').value.trim();p.organization=document.getElementById('auth-organization').value.trim();}try{const r=signup?await api.signup(p):await api.login(p);state.currentUser=r.user;state.csrf=r.user?.csrfToken||state.csrf;closeDrawer();state.route='dashboard';location.hash='dashboard';render();showToast(signup?'Account created.':'Signed in successfully.');}catch(err){if(error)error.textContent=err.message;else showToast(err.message);}}
async function logoutUser(){try{await api.logout();}catch(e){}state.currentUser=null;state.route='home';location.hash='home';render();showToast('Signed out.');}

async function submitInstrument(e){e.preventDefault();const p={type:document.getElementById('instrumentType').value,manufacturer:document.getElementById('manufacturer').value,model:document.getElementById('model').value,serial:document.getElementById('serial').value,capacity:document.getElementById('capacity').value,accuracyClass:document.getElementById('accuracyClass').value,installationDate:document.getElementById('installationDate').value,location:document.getElementById('location').value};try{const r=await api.createInstrument(p);state.selectedInstrument=r.id;closeDrawer();showToast(`Instrument ${r.id} registered.`);render();}catch(err){showToast(err.message);}}
async function submitApplication(e){e.preventDefault();const files=Array.from(document.getElementById('applicationFiles')?.files||[]);const documents=[];for(const f of files)documents.push({name:f.name,type:f.type,size:f.size,hash:await hashFile(f),contentBase64:f.size<=2*1024*1024?await fileToDataUrl(f):null});const p={type:document.getElementById('applicationType').value,instrumentId:document.getElementById('instrumentId').value,preferredDate:document.getElementById('preferredDate').value,centre:document.getElementById('centre').value,note:document.getElementById('note').value,documents};try{const r=await api.createApplication(p);state.selectedApplication=r.id;closeDrawer();showToast(`${r.id} submitted and fee marked paid in demo mode.`);render();}catch(err){showToast(err.message);}}
async function loadRecommendation(){const id=document.getElementById('scheduleApp').value.trim();if(!id){showToast('Enter an application ID first.');return;}try{const r=await api.recommend(id);document.getElementById('scheduleOfficer').value=r.recommendation.officerId;document.getElementById('recommendation-box')?.remove();const el=document.getElementById('schedule-recommendation');el.innerHTML=`<div class="recommendation-box"><strong>Recommended: ${esc(r.recommendation.officer)}</strong><span>${r.recommendation.distanceKm.toFixed(1)} km · workload ${r.recommendation.workload} · risk ${r.risk.score}</span><small>${esc(r.risk.recommendedAction)}</small></div>`; }catch(err){showToast(err.message);}}
async function submitSchedule(e){e.preventDefault();const id=document.getElementById('scheduleApp').value.trim();try{const r=await api.scheduleApplication(id,{date:document.getElementById('scheduleDate').value,slot:document.getElementById('scheduleSlot').value,officerId:document.getElementById('scheduleOfficer').value,centreId:document.getElementById('scheduleCentre').value});closeDrawer();showToast(`${r.id} scheduled.`);render();}catch(err){showToast(err.message);}}
async function startInspection(e){e.preventDefault();const p={instrumentId:document.getElementById('startInstrument').value,applicationId:document.getElementById('startApplication').value,location:document.getElementById('startLocation').value,slot:document.getElementById('startSlot').value};try{const r=await api.startInspection(p);state.selectedInspection=r.id;closeDrawer();showToast(`${r.id} opened.`);navigate('inspection');}catch(err){showToast(err.message);}}

let currentEvidence=[];
async function fileToDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
async function analyzeImageQuality(file){return new Promise(resolve=>{if(!file.type.startsWith('image/'))return resolve({label:'FILE',reason:'Non-image evidence'});const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{try{const max=180,scale=Math.min(1,max/Math.max(img.width,img.height));const w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,w,h);const d=ctx.getImageData(0,0,w,h).data;let sum=0,grad=0,n=0;for(let y=0;y<h;y++){for(let x=0;x<w;x++){const k=(y*w+x)*4;const g=0.299*d[k]+0.587*d[k+1]+0.114*d[k+2];sum+=g;n++;if(x>0){const pk=k-4;const pg=0.299*d[pk]+0.587*d[pk+1]+0.114*d[pk+2];grad+=Math.abs(g-pg);}if(y>0){const pk=k-w*4;const pg=0.299*d[pk]+0.587*d[pk+1]+0.114*d[pk+2];grad+=Math.abs(g-pg);}}}const brightness=sum/n;const sharpness=grad/n;const label=(img.width<640||img.height<480||brightness<35||brightness>240||sharpness<3)?'RETAKE RECOMMENDED':'GOOD';resolve({label,brightness:Number(brightness.toFixed(1)),sharpness:Number(sharpness.toFixed(1)),width:img.width,height:img.height});}catch{resolve({label:'CHECK MANUALLY'});}finally{URL.revokeObjectURL(url);}};img.onerror=()=>{URL.revokeObjectURL(url);resolve({label:'CHECK MANUALLY'});};img.src=url;});}
async function previewEvidence(input){currentEvidence=[];document.getElementById('evidence-list').innerHTML='';for(const file of Array.from(input.files)){const quality=await analyzeImageQuality(file);const item={name:file.name,type:file.type,size:file.size,hash:await hashFile(file),quality,contentBase64:file.size<=2*1024*1024?await fileToDataUrl(file):null};currentEvidence.push(item);}document.getElementById('evidence-list').innerHTML=currentEvidence.map(x=>`<div class="evidence-chip">${icon('file')}<span>${esc(x.name)}</span><small>${Math.round(x.size/1024)} KB · ${esc(x.quality?.label||'CHECK')}${x.contentBase64?' · stored':' · metadata only'}</small></div>`).join('');}
async function scanInspectionQr(inspectionId){try{if('BarcodeDetector' in window&&navigator.mediaDevices?.getUserMedia){const overlay=document.createElement('div');overlay.className='certificate-modal-overlay open';overlay.id='qr-scan-overlay';overlay.innerHTML=`<section class="certificate-modal" style="max-width:620px"><header class="certificate-modal-head"><div><span class="eyebrow page-eyebrow">Field capture</span><h2>Scan certificate QR</h2><p>Point the camera at the Veriq certificate sticker.</p></div><button class="close-btn" onclick="stopQrScanner()">${icon('close')}</button></header><div style="padding:18px"><video id="qr-scan-video" autoplay playsinline style="width:100%;border-radius:16px;background:#3e2a20;min-height:280px"></video><p id="qr-scan-status" style="margin-top:12px">Starting camera…</p></div></section>`;document.body.appendChild(overlay);const video=document.getElementById('qr-scan-video');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});video.srcObject=stream;const detector=new BarcodeDetector({formats:['qr_code']});window.__qrScanner={stream,timer:null};const tick=async()=>{try{const codes=await detector.detect(video);if(codes.length){const raw=String(codes[0].rawValue||'');const m=raw.match(/public-verify[\/#]+([^/?#]+)/i);const certId=m?decodeURIComponent(m[1]):raw.split('/').pop();window.__qrScanner.timer=null;stopQrScanner();const r=await api.inspectionQrCheck(inspectionId,{certificateId:certId,visibleSerial:document.getElementById('captured-serial')?.value||''});if(r.ok){document.getElementById('captured-serial').value=r.registeredSerial||document.getElementById('captured-serial').value;showToast(`QR VERIFIED · ${r.certificateId}`);}else showToast(`QR check: ${r.status}`);return;}}catch{}window.__qrScanner.timer=requestAnimationFrame(tick);};window.__qrScanner.timer=requestAnimationFrame(tick);}else{const certId=prompt('Enter the certificate ID from the QR, e.g. CERT-2026-3421');if(!certId)return;const r=await api.inspectionQrCheck(inspectionId,{certificateId:certId,visibleSerial:document.getElementById('captured-serial')?.value||''});if(r.ok)showToast(`QR VERIFIED · ${r.certificateId}`);else showToast(`QR check: ${r.status}`);}}catch(e){stopQrScanner();showToast(e.message||'QR scan failed.');}}
function stopQrScanner(){const x=window.__qrScanner;if(x?.timer)cancelAnimationFrame(x.timer);x?.stream?.getTracks?.().forEach(t=>t.stop());window.__qrScanner=null;document.getElementById('qr-scan-overlay')?.remove();}

async function hashFile(file){const buf=await file.arrayBuffer();return [...new Uint8Array(await crypto.subtle.digest('SHA-256',buf))].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function captureGps(){const out=document.getElementById('gps-value');if(!navigator.geolocation){showToast('Geolocation is not available in this browser.');return;}navigator.geolocation.getCurrentPosition(p=>{out.value=`${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)} ±${Math.round(p.coords.accuracy)}m`;out.dataset.lat=p.coords.latitude;out.dataset.lng=p.coords.longitude;out.dataset.acc=p.coords.accuracy;const badge=document.getElementById('evidence-gps');if(badge)badge.textContent='Captured';showToast('GPS captured.');},()=>showToast('GPS permission was not granted.'));}
function testReadings(){const expected=[...document.querySelectorAll('.inspection-expected')],observed=[...document.querySelectorAll('.inspection-observed')];const rule=state.currentInspectionRule||{mpePercent:0.1};return expected.map((x,i)=>{const e=parseFloat(x.value),o=parseFloat(observed[i]?.value);if(Number.isNaN(e)||Number.isNaN(o))return null;const mpe=Math.abs(e)*Number(rule.mpePercent||0.1)/100;const err=Math.abs(o-e);return {test:`Test ${i+1}`,expected:e,observed:o,error:Number(err.toFixed(6)),mpe:Number(mpe.toFixed(6)),unit:rule.unit||'configured',pass:err<=mpe};}).filter(Boolean);}
async function submitInspection(e){e.preventDefault();const readings=testReadings();const result=document.getElementById('inspection-result').value;const gps=document.getElementById('gps-value');const payload={result,offline:document.getElementById('offline-mode').checked,testReadings:readings,evidence:currentEvidence,gps:gps?.dataset?.lat?{lat:Number(gps.dataset.lat),lng:Number(gps.dataset.lng),accuracy:Number(gps.dataset.acc||0)}:null,deviceId:`WEB-${navigator.platform||'FIELD'}`,capturedSerial:document.getElementById('captured-serial')?.value.trim()||'',note:document.getElementById('inspection-note')?.value||''};if(payload.offline){await saveOfflinePayload(state.selectedInspection,payload);showToast('Inspection saved locally. Use Sync offline when connectivity returns.');return;}try{const r=await api.submitInspection(state.selectedInspection,payload);showToast(r.certificate?`Verification complete. ${r.certificate.id} issued.`:'Inspection submitted.');state.selectedInstrument=r.instrument.id;render();}catch(err){await saveOfflinePayload(state.selectedInspection,payload);showToast(`Network unavailable. Draft saved offline: ${err.message}`);}}
function getOfflineDraftMeta(){try{return JSON.parse(localStorage.getItem(offlineKey)||'[]')}catch{return[]}}
async function getOfflineCryptoKey(){if(!window.crypto?.subtle)return null;return new Promise((resolve,reject)=>{const req=indexedDB.open('veriq-secure',1);req.onupgradeneeded=()=>req.result.createObjectStore('keys');req.onerror=()=>reject(req.error);req.onsuccess=async()=>{const db=req.result;const tx=db.transaction('keys','readwrite');const store=tx.objectStore('keys');const get=store.get('offline-key');get.onsuccess=async()=>{if(get.result){resolve(get.result);return;}const key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},true,['encrypt','decrypt']);store.put(key,'offline-key');resolve(key);};get.onerror=()=>reject(get.error);};});}
function bytesToB64(bytes){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s);}
function b64ToBytes(s){const bin=atob(s);return Uint8Array.from(bin,c=>c.charCodeAt(0));}
async function encryptOffline(payload){const key=await getOfflineCryptoKey();if(!key)return {plain:true,payload};const iv=crypto.getRandomValues(new Uint8Array(12));const encoded=new TextEncoder().encode(JSON.stringify(payload));const ciphertext=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,encoded));return {encrypted:true,iv:bytesToB64(iv),ciphertext:bytesToB64(ciphertext)};}
async function decryptOffline(row){if(row.plain)return row.payload;const key=await getOfflineCryptoKey();const data=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(row.iv)},key,b64ToBytes(row.ciphertext));return JSON.parse(new TextDecoder().decode(data));}
async function getOfflineDrafts(){const rows=getOfflineDraftMeta();const out=[];for(const row of rows){try{out.push({id:row.id,payload:await decryptOffline(row),savedAt:row.savedAt});}catch(e){console.warn('Offline draft decrypt failed',e);}}return out;}
async function saveOfflinePayload(id,payload){const existing=getOfflineDraftMeta().filter(x=>x.id!==id);const encrypted=await encryptOffline(payload);existing.push({id,...encrypted,savedAt:new Date().toISOString()});localStorage.setItem(offlineKey,JSON.stringify(existing));}
async function saveOfflineDraft(id){const p={result:document.getElementById('inspection-result')?.value||'PASS',offline:true,testReadings:testReadings(),evidence:currentEvidence,gps:document.getElementById('gps-value')?.dataset?.lat?{lat:Number(document.getElementById('gps-value').dataset.lat),lng:Number(document.getElementById('gps-value').dataset.lng),accuracy:Number(document.getElementById('gps-value').dataset.acc||0)}:null,deviceId:`WEB-${navigator.platform||'FIELD'}`,capturedSerial:document.getElementById('captured-serial')?.value.trim()||''};await saveOfflinePayload(id,p);showToast('Encrypted browser offline draft queued. It will sync when connectivity returns.');}
async function syncOffline(){const rows=await getOfflineDrafts();if(!rows.length){showToast('No offline drafts are waiting.');return;}let synced=0;const remaining=[];for(const row of rows){try{await api.submitInspection(row.id,row.payload);synced++;}catch(e){remaining.push(row);}}const stored=[];for(const row of remaining){stored.push({id:row.id,...await encryptOffline(row.payload),savedAt:row.savedAt});}localStorage.setItem(offlineKey,JSON.stringify(stored));showToast(`${synced} offline inspection draft(s) synchronized.`);render();}

async function publicVerifyPage(certId=''){const code=certId||'';return `<div class="public-shell"><nav class="landing-nav">${brand()}<div class="nav-links"><a href="#home">Home</a><a href="#how-it-works">Workflow</a></div><div class="nav-actions"><button class="btn btn-light" onclick="location.hash='home'">Back to home</button></div></nav><section class="hero" style="min-height:auto;padding:60px 7vw 30px"><div class="hero-copy"><span class="eyebrow">PUBLIC TRUST PORTAL</span><h1>Verify an instrument.<br><em>Without an account.</em></h1><p>Check the live certificate, physical identity match, expiry, revocation and location consistency from one public verification page.</p></div><div class="hero-visual"><div class="glass-orb" style="min-height:260px"><div class="orb-inner-glow"></div><div class="orb-platform"><span></span></div><div style="font-size:72px;color:#a87850">✓</div></div></div></section><section class="landing-section" style="padding-top:20px"><div class="panel" style="max-width:1000px;margin:0 auto"><div class="panel-head"><div><span class="panel-kicker">Live registry check</span><h3>Certificate verification</h3><p>Optionally enter the visible serial number on the physical instrument to detect QR cloning.</p></div></div><div class="form-grid"><div class="field"><label>Certificate ID</label><input id="publicVerifyCode" value="${esc(code)}" placeholder="e.g. CERT-2026-3421"></div><div class="field"><label>Visible serial number</label><input id="publicVerifySerial" placeholder="e.g. WTX-239812"></div></div><div class="drawer-actions-inline"><button class="btn btn-primary" onclick="runPublicVerify()">${icon('shield')} Verify now</button><button class="btn btn-light" onclick="capturePublicVerifyLocation()">${icon('pin')} Use my location</button></div><div id="public-verify-result" style="margin-top:20px"></div></div></section></div>`;}
let publicVerifyLocation=null;async function capturePublicVerifyLocation(){if(!navigator.geolocation){showToast('Geolocation is not available in this browser.');return;}navigator.geolocation.getCurrentPosition(p=>{publicVerifyLocation={lat:p.coords.latitude,lng:p.coords.longitude};showToast('Location captured. Run verification again to include location consistency.');},()=>showToast('Location permission was not granted.'));}
async function runPublicVerify(){const code=document.getElementById('publicVerifyCode')?.value.trim();const serial=document.getElementById('publicVerifySerial')?.value.trim();const out=document.getElementById('public-verify-result');if(!code){showToast('Enter a certificate ID.');return;}try{const r=await api.verify(code,serial,publicVerifyLocation);out.innerHTML=verifyMarkup(r);if(r.instrument?.id){state.selectedInstrument=r.instrument.id;}}catch(err){out.innerHTML=`<div class="verify-result-card danger"><div class="verify-result-head"><span class="status danger">NOT FOUND</span><strong>Certificate record not found</strong></div><p>${esc(err.message)}</p></div>`;}}

function verifyMarkup(data){const c=data.checks;const status=c.status;return `<div class="verify-result-card ${statusClass(status)}"><div class="verify-result-head"><span class="status ${statusClass(status)}">${esc(status)}</span><strong>${status==='VERIFIED'?'Trust chain validated':status==='MISMATCH'?'Physical identity mismatch':status==='EXPIRED'?'Certificate expired':status==='REVOKED'?'Certificate revoked':'Record not found'}</strong></div>${data.instrument?`<div class="verify-summary"><div><span>Instrument</span><b>${esc(data.instrument.id)}</b></div><div><span>Serial</span><b>${esc(data.instrument.serial)}</b></div><div><span>Type</span><b>${esc(data.instrument.type)}</b></div><div><span>Manufacturer</span><b>${esc(data.instrument.manufacturer||data.instrument.make||'—')}</b></div><div><span>Valid until</span><b>${esc(data.certificate.validToLabel)}</b></div></div><div class="verify-checks">${[['Digital signature',c.signatureValid],['Instrument ID',c.idMatch],['Serial number',c.serialMatch],['Certificate active',!c.revoked],['Not expired',!c.expired],['Location consistency',c.jurisdictionMatch]].map(x=>`<div><span class="check-dot ${x[1]?'ok':'bad'}">${x[1]?'✓':'!'}</span><span>${x[0]}</span><b>${x[1]?'PASS':'CHECK'}</b></div>`).join('')}</div><button class="btn btn-light" onclick="state.selectedInstrument='${esc(data.instrument?.id||'')}';openDrawer('complaint')">Report this instrument</button>`:`<p>Nothing matched the registry.</p>`}</div>`;}
async function verifyCode(){const code=document.getElementById('verifyCode').value.trim();const serial=document.getElementById('verifySerial').value.trim();const out=document.getElementById('verify-result');if(!code){showToast('Enter a certificate ID.');return;}try{const r=await api.verify(code,serial);out.innerHTML=verifyMarkup(r);state.selectedInstrument=r.instrument?.id||state.selectedInstrument;}catch(err){out.innerHTML=`<div class="verify-result-card danger"><div class="verify-result-head"><span class="status danger">NOT FOUND</span><strong>Certificate record not found</strong></div><p>${esc(err.message)}</p></div>`;}}

function openCertificate(id){api.certificate(id).then(c=>{document.body.insertAdjacentHTML('beforeend',certificateModalMarkup(c));requestAnimationFrame(()=>{document.querySelector('.certificate-modal-overlay:last-of-type')?.classList.add('open');renderQrInto(document.querySelector('.certificate-modal:last-of-type .certificate-qr'),`/#public-verify/${c.id}`);});}).catch(e=>showToast(e.message));}
function certificateModalMarkup(c){return `<div class="certificate-modal-overlay" onclick="if(event.target===this)closeCertificate()"><section class="certificate-modal"><header class="certificate-modal-head"><div><span class="eyebrow page-eyebrow">Digital verification record</span><h2>${esc(c.id)}</h2><p>${esc(c.status)} · version ${c.version}</p></div><button class="close-btn" onclick="closeCertificate()">${icon('close')}</button></header><div class="certificate-proof"><div class="certificate-proof-icon">${icon('shield')}</div><div><strong>Server registry check</strong><span>${esc(c.checks.status)} · signature ${esc(c.signature.slice(0,16))}…</span></div><div class="certificate-qr" data-qr="/#public-verify/${esc(c.id)}"></div></div><div class="certificate-detail-grid"><article class="certificate-detail-card"><span>Instrument details</span><h3>${esc(c.instrument.type)}</h3><dl><dt>Instrument ID</dt><dd>${esc(c.instrument.id)}</dd><dt>Manufacturer / model</dt><dd>${esc(c.instrument.make)} · ${esc(c.instrument.model)}</dd><dt>Serial</dt><dd>${esc(c.instrument.serial)}</dd><dt>Capacity</dt><dd>${esc(c.instrument.capacity)}</dd><dt>Accuracy</dt><dd>${esc(c.instrument.accuracyClass)}</dd></dl></article><article class="certificate-detail-card"><span>Certificate lifecycle</span><h3>${esc(c.status)}</h3><dl><dt>Issued</dt><dd>${fmtDate(c.issuedAt)}</dd><dt>Valid until</dt><dd>${esc(c.validToLabel)}</dd><dt>Issuer</dt><dd>${esc(c.issuer)}</dd><dt>Signature</dt><dd class="mono-cell">${esc(c.signatureAlgorithm||'HMAC-SHA256')} · ${esc(c.signature.slice(0,28))}…</dd><dt>Evidence hash</dt><dd class="mono-cell">${esc(c.evidenceHash||'—')}</dd><dt>Rule package</dt><dd>${esc(c.ruleId||'—')}</dd></dl></article><article class="certificate-detail-card full"><span>Trust checks</span><div class="formalities">${[['Signature valid',c.checks.signatureValid],['Instrument ID matched',c.checks.idMatch],['Serial matched',c.checks.serialMatch],['Not revoked',!c.revokedAt],['Not expired',!c.checks.expired]].map(x=>`<div><span>${icon(x[1]?'check':'warning')}</span>${x[0]}</div>`).join('')}</div></article></div><footer class="certificate-modal-actions"><button class="btn btn-light" onclick="window.open('/api/certificates/${c.id}/print','_blank')">${icon('download')} Print / Save PDF</button><button class="btn btn-light" onclick="publishDigiLocker('${esc(c.id)}')">${icon('file')} ${c.digilockerStatus?.includes('Published')?'Published':'Publish to DigiLocker demo'}</button><button class="btn btn-light" onclick="demoEsign('${esc(c.id)}')">${c.esignHash?'eSigned':'eSign demo'}</button><button class="btn btn-light" onclick="pushEmaap('${esc(c.id)}')">${c.emaapStatus?'eMaap demo sent':'Send to eMaap demo'}</button><button class="btn btn-light" onclick="openScanAnalytics('${esc(c.id)}')">Scan analytics</button><button class="btn btn-light" onclick="emailCertificate('${esc(c.id)}')">Email</button>${state.currentUser?.role==='business'&&c.status!=='Revoked'?`<button class="btn btn-primary" onclick="renewCertificate('${esc(c.id)}')">Re-verify / Renew</button>`:''}${['lmo','admin'].includes(state.currentUser?.role)&&!c.revokedAt?`<button class="btn btn-primary" onclick="revokeCertificate('${esc(c.id)}')">Revoke certificate</button>`:''}</footer></section></div>`;}
function closeCertificate(){document.querySelectorAll('.certificate-modal-overlay').forEach(x=>x.remove());}
async function revokeCertificate(id){const reason=prompt('Reason for revocation','Certificate integrity concern');if(reason===null)return;try{await api.revokeCertificate(id,{reason});closeCertificate();showToast('Certificate revoked. Public verification will update immediately.');render();}catch(e){showToast(e.message);}}
async function publishDigiLocker(id){try{const r=await api.publishDigiLocker(id);showToast(`Demo DigiLocker issuer published ${r.documentUri}.`);closeCertificate();render();}catch(e){showToast(e.message);}}
async function demoEsign(id){try{await api.esignCertificate(id);showToast('Demo eSign complete. Production deployment should use approved eSign/DSC.');closeCertificate();render();}catch(e){showToast(e.message);}}
async function pushEmaap(id){try{await api.pushEmaap(id);showToast('eMaap demo adapter accepted the certificate.');closeCertificate();render();}catch(e){showToast(e.message);}}
function emailCertificate(id){const url=`${location.origin}/#public-verify/${encodeURIComponent(id)}`;location.href=`mailto:?subject=${encodeURIComponent('Veriq certificate '+id)}&body=${encodeURIComponent('Verify this certificate: '+url)}`;}

async function resolveComplaint(id){const resolution=prompt('Resolution / action','Inspection scheduled based on public complaint');if(resolution===null)return;try{await api.resolveComplaint(id,{resolution});showToast('Complaint resolved and audit recorded.');render();}catch(e){showToast(e.message);}}
async function resolveFraud(id){if(!confirm('Mark this fraud signal as reviewed/resolved?'))return;try{await api.resolveFraud(id);showToast('Fraud signal resolved.');render();}catch(e){showToast(e.message);}}
async function submitPublicComplaint(e){e.preventDefault();const files=document.getElementById('complaintFiles')?.files||[];const evidence=[];for(const f of files)evidence.push({name:f.name,type:f.type,size:f.size,hash:await hashFile(f),contentBase64:f.size<=2*1024*1024?await fileToDataUrl(f):null});try{const r=await api.publicComplaint({instrumentId:document.getElementById('complaintInstrument').value,category:document.getElementById('complaintCategory').value,description:document.getElementById('complaintDescription').value,location:document.getElementById('complaintLocation').value,evidence});closeDrawer();showToast(`Complaint ${r.id} submitted.`);if(state.route!=='home')render();}catch(err){showToast(err.message);}}

async function loadApplicationDetail(){const root=document.getElementById('application-detail-body');if(!root)return;const rows=await api.applications();const a=rows.find(x=>x.id===state.selectedApplication);if(!a){root.innerHTML='<div class="empty-state"><h3>Application not found</h3></div>';return;}root.innerHTML=`<div class="detail-flow"><div class="flow-step is-done">Submitted</div><div class="flow-line"></div><div class="flow-step ${a.status!=='Under Review'?'is-done':''}">Validated</div><div class="flow-line"></div><div class="flow-step ${a.status==='Scheduled'||a.status==='Approved'?'is-done':''}">Scheduled</div><div class="flow-line"></div><div class="flow-step ${a.status==='Approved'?'is-done':''}">Decision</div></div><div class="application-detail-card"><div><span>Application</span><h3>${esc(a.id)}</h3></div><div><span>Instrument</span><b>${esc(a.instrumentId)}</b></div><div><span>Status</span><span class="status ${statusClass(a.status)}">${esc(a.status)}</span></div><div><span>Fee</span><span class="status verified">${esc(a.feeStatus)}</span></div></div><section class="panel" style="margin-top:14px;padding:16px"><div class="panel-head"><div><h3>Supporting documents</h3><span>${a.documents?.length||0} stored evidence file(s)</span></div></div><div class="activity-list">${(a.documents||[]).map(d=>`<div class="activity"><div class="activity-icon">${icon('file')}</div><div><strong>${esc(d.name)}</strong><span>${Math.round((d.size||0)/1024)} KB · ${esc(d.hash?.slice(0,16)||'no hash')}…</span></div><a class="btn btn-light btn-small" href="/api/evidence/${encodeURIComponent(d.id)}" target="_blank">Open</a></div>`).join('')||'<div class="empty-state compact"><p>No supporting documents uploaded.</p></div>'}</div></section><div class="drawer-actions-inline">${['lmo','gatc','admin'].includes(state.currentUser.role)&&['Under Review','Submitted'].includes(a.status)?`<button class="btn btn-light" onclick="approveApp('${a.id}')">Approve</button><button class="btn btn-light" onclick="closeDrawer();state.selectedApplication='${a.id}';openDrawer('reject')">Reject</button>`:''}${['lmo','gatc','admin'].includes(state.currentUser.role)&&['Approved','Under Review'].includes(a.status)?`<button class="btn btn-primary" onclick="closeDrawer();state.selectedApplication='${a.id}';openDrawer('schedule')">Schedule</button>`:''}${state.currentUser.role==='business'&&a.status==='Rejected'?`<button class="btn btn-primary" onclick="resubmitApp('${a.id}')">Resubmit</button>`:''}${state.currentUser.role==='business'&&['Submitted','Under Review'].includes(a.status)?`<button class="btn btn-primary" onclick="closeDrawer();state.selectedInstrument='${a.instrumentId}';openDrawer('application')">Continue application</button>`:''}${state.currentUser.role==='business'&&a.status==='Completed'?`<button class="btn btn-light" onclick="renewApplication('${a.id}')">Create re-verification</button>`:''}</div>`;}
async function approveApp(id){try{await api.approveApplication(id);closeDrawer();showToast('Application approved.');render();}catch(e){showToast(e.message);}}
async function submitReject(e){e.preventDefault();try{await api.rejectApplication(state.selectedApplication,{reason:document.getElementById('rejectReason').value});closeDrawer();showToast('Application rejected with recorded reason.');render();}catch(err){showToast(err.message);}}
async function resubmitApp(id){try{await api.resubmitApplication(id,{});closeDrawer();showToast('Application resubmitted for review.');render();}catch(err){showToast(err.message);}}
async function renewCertificate(id){try{const r=await api.renewCertificate(id);closeCertificate();showToast(`Re-verification ${r.id} created.`);state.selectedApplication=r.id;openDrawer('application-detail');}catch(e){showToast(e.message);}}
async function requestReinspection(id){try{const r=await api.reinspect(id);showToast(`Re-inspection ${r.id} created.`);state.selectedApplication=r.id;openDrawer('application-detail');}catch(e){showToast(e.message);}}
async function renewApplication(id){try{const r=await api.request(`/api/applications/${encodeURIComponent(id)}/renew`,{method:'POST',body:'{}'});closeDrawer();showToast(`Re-verification ${r.id} created.`);state.selectedApplication=r.id;openDrawer('application-detail');}catch(e){showToast(e.message);}}
async function captureRelocationGps(){if(!navigator.geolocation)return showToast('Geolocation is not available in this browser.');navigator.geolocation.getCurrentPosition(p=>{const a=document.getElementById('relocateLat'),b=document.getElementById('relocateLng');if(a)a.value=p.coords.latitude.toFixed(6);if(b)b.value=p.coords.longitude.toFixed(6);showToast('Relocation GPS captured.');},()=>showToast('GPS permission was not granted.'));}
async function submitRelocation(e){e.preventDefault();try{await api.relocateInstrument(document.getElementById('relocateInstrument').value,{location:document.getElementById('relocateLocation').value,lat:Number(document.getElementById('relocateLat').value)||undefined,lng:Number(document.getElementById('relocateLng').value)||undefined});closeDrawer();showToast('Location updated; revalidation signal created.');render();}catch(err){showToast(err.message);}}
async function submitRepair(e){e.preventDefault();const files=Array.from(document.getElementById('repairFiles')?.files||[]);const evidence=[];for(const f of files)evidence.push({name:f.name,type:f.type,size:f.size,hash:await hashFile(f),contentBase64:f.size<=2*1024*1024?await fileToDataUrl(f):null});try{await api.createRepair({instrumentId:document.getElementById('repairInstrument').value,date:document.getElementById('repairDate').value,repairer:document.getElementById('repairer').value,reason:document.getElementById('repairReason').value,evidence});closeDrawer();showToast('Repair recorded; risk and re-verification signals updated.');render();}catch(err){showToast(err.message);}}
async function submitFeedback(e){e.preventDefault();const complaintId=document.getElementById('feedbackComplaintId')?.value;const inspectionId=document.getElementById('feedbackInspectionId')?.value;try{const payload={rating:Number(document.getElementById('feedbackRating').value),comment:document.getElementById('feedbackComment').value};if(inspectionId)await api.feedbackInspection(inspectionId,payload);else if(complaintId)await api.feedbackComplaint(complaintId,payload);else throw new Error('No feedback target selected.');closeDrawer();showToast('Feedback submitted.');render();}catch(err){showToast(err.message);}}


function showNotifications(){api.notifications().then(rows=>{const text=rows.length?rows.map(x=>`${x.title}: ${x.message}`).join('\n\n'):'You are all caught up.';alert(text);api.readNotifications().catch(()=>{});}).catch(()=>{});}
function downloadCsv(rows,file){if(!Array.isArray(rows)||!rows.length){showToast('Nothing to export.');return;}const keys=Object.keys(rows[0]);const csv=[keys.join(','),...rows.map(r=>keys.map(k=>`"${String(r[k]??'').replace(/"/g,'""')}"`).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=file;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}

function renderQrInto(el,data){if(!el)return;if(window.qrcode){try{const qr=qrcode(0,'M');qr.addData(location.origin+data);qr.make();el.innerHTML=qr.createSvgTag({cellSize:3,margin:1});return;}catch(e){}}el.innerHTML=`<div class="qr-fallback"><strong>QR</strong><span>${esc(data)}</span></div>`;}
function renderQrs(){document.querySelectorAll('[data-qr]').forEach(el=>renderQrInto(el,el.dataset.qr));}

window.addEventListener('hashchange',()=>{state.route=location.hash.replace('#','')||'home';render();});
(async function bootstrap(){try{const h=await api.health();document.body.dataset.apiStatus=h.storage;const me=await api.me();state.currentUser=me.user||null;state.csrf=me.user?.csrfToken||'';}catch(e){state.currentUser=null;}render();})();
